<template>
  <div class="backRateRecord">
    <title-line :title="title" />
    <div class="navList">
      <div v-for="(item,index) in datalist" :key="index" class="nav" @click="tabClick(index)">
        <!-- <image-pic contain class="img-pic" height="100%" width="100%" :src="currentTab===index?item.activeurl:item.smallurl" alt="" /> -->
        <div :class="currentTab===index?'typeName active':'typeName'">{{ item.gamemenutypename }}</div>
      </div>
    </div>
    <div class="sublist">
      <div v-for="(item,index) in gameSecList" :key="index" :class="index===currentSubTab?'filterItem filterItemActive':'filterItem'" @click="subtabClick(index)">
        <div class="text">{{ item.gametypename }}</div>
      </div>
    </div>
    <div class="commisRecord-content">
      <div class="recordBox">
        <div class="thead">
          <span>{{$t('yjjlbl.yjjlbl02')}}</span>
          <span>{{$t('yjjlbl.yjjlbl03')}}</span>
        </div>
        <div class="tbody">
          <div v-for="(item,index) in recordList" :key="index" class="list">
            <span>{{ item.levelname }}</span>
            <span style="color:#FFBF23;font-family: HelveticaNeue-Bold;font-weight:700">{{ item.backs }}</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { vipagent, getUInfoByToken, getGameplayList } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: this.$t('yjjlbl.yjjlbl01'),
      recordList: [
      ],
      datalist: [],
      gameSecList: [],
      currentTab: 0,
      currentSubTab: 0
    }
  },
  created() {
    this.onLoad()
    // getUInfoByToken().then(res => {
    //   this.datalist = res.datalist
    // })
  },
  methods: {
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    tabClick(index) {
      this.currentTab = index
      this.currentSubTab = 0
      this.onLoad()
    },
    subtabClick(index) {
      this.currentSubTab = index
      this.onLoad()
    },
    async onLoad() {
      const res = await vipagent()
      this.datalist = res.datalist
      this.gameSecList = res.datalist[this.currentTab].gametypenamelist
      this.recordList = res.datalist[this.currentTab].gametypenamelist[this.currentSubTab].vipagentlist
    }
  }

}
</script>
